import {chromium} from '@playwright/test';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import sharp from 'sharp';
const record=JSON.parse(await readFile(process.argv[2],'utf8')),root='.local/step07/fix-round3/final/restored-browser-complete';await mkdir(root,{recursive:true});
const browser=await chromium.launch(),page=await browser.newPage({viewport:{width:1200,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:4376');const p=record.restoredState.projectId;await page.evaluate(id=>localStorage.setItem('studio-project',id),p);await page.reload();await page.getByRole('heading',{name:'交付预览与构建历史'}).waitFor();await page.getByText('画布已就绪 · 实际导出图集',{exact:false}).waitFor({timeout:30000});const canvas=page.locator('canvas[aria-label="交付拼接预览"]');
const build=await canvas.getAttribute('data-build-id');if(build!==record.rebuilt)throw Error('restored current differs from actual rebuilt Build');const png=page.getByAltText('当前配方处理水面');await png.waitFor({timeout:60000});await page.waitForFunction(()=>{const i=document.querySelector('img[alt="当前配方处理水面"]');return i?.complete&&i.naturalWidth===96&&i.naturalHeight===144;});
const image=await png.evaluate(i=>{const c=document.createElement('canvas');c.width=96;c.height=144;c.getContext('2d').drawImage(i,0,0);return {project:i.dataset.projectId,recipe:i.dataset.recipeId,frame:Number(i.dataset.sourceFrame),pngSha:i.dataset.pngSha256,width:i.naturalWidth,height:i.naturalHeight,rgba:Array.from(c.getContext('2d').getImageData(0,0,96,144).data)};});
if(image.project!==p)throw Error('restored processed project mismatch');
const response=await page.request.get(`http://127.0.0.1:4376/api/projects/${p}/recipes/${image.recipe}/processed?frame=${image.frame}`);if(response.status()!==200)throw Error('restored actual processed PNG failed');const pngBytes=await response.body();const raw=await sharp(pngBytes).ensureAlpha().raw().toBuffer();
if(createHash('sha256').update(pngBytes).digest('hex')!==image.pngSha||!raw.equals(Buffer.from(image.rgba)))throw Error('restored processed actual PNG/pixels mismatch');delete image.rgba;
const state=await(await page.request.get(`http://127.0.0.1:4376/api/projects/${p}/studio`)).json();if(state.successfulBuildId!==record.rebuilt||!state.recipes.some(r=>r.id===image.recipe)||state.sources.length!==record.restoredState.sources.length)throw Error('restored source/recipe/build mismatch');
await page.screenshot({path:root+'/restored-current.png',fullPage:true});
await page.getByLabel('实际构建').selectOption(record.first);await page.waitForFunction(expected=>document.querySelector('canvas[aria-label="交付拼接预览"]')?.getAttribute('data-build-id')===expected,record.first);await page.getByText('画布已就绪 · 实际导出图集',{exact:false}).waitFor();
const event=page.waitForEvent('download');await page.getByRole('link',{name:'下载此构建的标准 MZ 素材包 ZIP'}).click();const download=await event;await download.saveAs(root+'/restored-history.zip');const bytes=await readFile(root+'/restored-history.zip'),sha=createHash('sha256').update(bytes).digest('hex');if(sha!==record.zipSha)throw Error('restored historical ZIP changed');await page.screenshot({path:root+'/restored-history.png',fullPage:true});
await writeFile(root+'/evidence.json',JSON.stringify({owner:'step07 author real restored browser',projectId:p,restoredBuild:build,historicalBuild:record.first,processedImage:image,actualSourceCount:state.sources.length,actualRecipeCount:state.recipes.length,actualBuildCount:state.builds.length,zipSha:sha,expectedZipSha:record.zipSha,errors,sourceSHA:'ef30dc2ab011d204d1d0a4d099a335b68458cdca'},null,2)+'\n');await browser.close();if(errors.length)throw Error('page errors');console.log('RESTORED_BROWSER_CURRENT_HISTORY_ZIP_PASS');
